// *** CORRECT: publish event inside TX, listener fires ONLY after commit ***
package com.bank.imps.service;

import com.bank.imps.dto.ImpsRequest;
import com.bank.imps.event.TransferCompletedEvent;
import com.bank.imps.model.Account;
import com.bank.imps.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
@Slf4j
public class GoodImpsService {

    private final AccountRepository accountRepo;
    private final ApplicationEventPublisher eventPublisher;

    /**
     * CORRECT: no external side effects inside TX.
     * Publish a domain event — the listener sends SMS ONLY after commit.
     *
     * Scenario: transfer SAV2001 → FRZ9001 (frozen)
     * 1. debit SAV2001
     * 2. publish event (queued — NOT delivered yet)
     * 3. credit FRZ9001: THROWS → TX ROLLBACK
     * 4. AFTER_ROLLBACK listener fires → no success SMS sent!
     * 5. Customer does NOT receive false SMS (Recommended) 
     *
     * Scenario: transfer SAV2001 → CUR3001 (active)
     * 1. debit SAV2001
     * 2. publish event
     * 3. credit CUR3001: success
     * 4. COMMIT
     * 5. AFTER_COMMIT listener fires → SMS sent! (Recommended) 
     */
    @Transactional(rollbackFor = Exception.class)
    public String transferGood(ImpsRequest request) {
        Account from = accountRepo.findById(request.fromAccountId()).orElseThrow();
        Account to = accountRepo.findById(request.toAccountId()).orElseThrow();

        from.debit(request.amount());
        to.credit(request.amount());  // may throw for frozen account

        accountRepo.save(from);
        accountRepo.save(to);

        // Publish event — delivered to listener ONLY after TX outcome is known
        eventPublisher.publishEvent(new TransferCompletedEvent(
            request.fromAccountId(), request.toAccountId(),
            request.amount(), from.getPhone()));

        log.info("[GOOD] TX body done. SMS will fire AFTER commit (not now).");
        return "COMPLETED";
    }
}
